import pytest
from candidate import triples_sum_to_zero


class TestTriplesSumToZero(unittest.TestCase):
    def test_returns_true_for_valid_triplet(self):
        self.assertTrue(triples_sum_to_zero([1, 3, -2, 1]))

    def test_returns_false_for_no_valid_triplet(self):
        self.assertFalse(triples_sum_to_zero([1, 3, 5, 0]))

    def test_returns_false_for_positive_numbers_only(self):
        self.assertFalse(triples_sum_to_zero([1, 2, 3, 7]))

    def test_returns_true_for_multiple_elements_with_triplet(self):
        self.assertTrue(triples_sum_to_zero([2, 4, -5, 3, 9, 7]))

    def test_returns_false_for_single_element(self):
        self.assertFalse(triples_sum_to_zero([1]))

    def test_returns_false_for_empty_list(self):
        self.assertFalse(triples_sum_to_zero([]))

    def test_returns_false_for_two_elements(self):
        self.assertFalse(triples_sum_to_zero([1, -1]))

    def test_returns_true_for_three_elements_summing_to_zero(self):
        self.assertTrue(triples_sum_to_zero([-1, 0, 1]))

    def test_returns_false_for_three_elements_not_summing_to_zero(self):
        self.assertFalse(triples_sum_to_zero([1, 2, 3]))

    def test_returns_true_for_zeros(self):
        self.assertTrue(triples_sum_to_zero([0, 0, 0]))

    def test_returns_true_for_duplicate_values(self):
        self.assertTrue(triples_sum_to_zero([1, 1, -2]))

    def test_returns_true_for_negative_triplet(self):
        self.assertTrue(triples_sum_to_zero([5, -3, -2]))

    def test_returns_true_for_large_numbers(self):
        self.assertTrue(triples_sum_to_zero([1000000, -500000, -500000]))

    def test_returns_false_for_large_numbers_no_triplet(self):
        self.assertFalse(triples_sum_to_zero([1000000, 2000000, 3000000]))

    def test_returns_true_for_mixed_positive_negative(self):
        self.assertTrue(triples_sum_to_zero([-5, 2, 3, 10]))

    def test_returns_false_for_all_negatives(self):
        self.assertFalse(triples_sum_to_zero([-1, -2, -3]))

    def test_returns_true_for_triplet_not_consecutive(self):
        self.assertTrue(triples_sum_to_zero([10, 20, 30, -10, 50]))

    def test_returns_true_for_first_three_elements(self):
        self.assertTrue(triples_sum_to_zero([1, 2, -3, 100]))

    def test_returns_true_for_last_three_elements(self):
        self.assertTrue(triples_sum_to_zero([100, 200, 1, 2, -3]))

    def test_returns_true_for_middle_triplet(self):
        self.assertTrue(triples_sum_to_zero([100, 4, -1, -3, 200]))

    def test_returns_false_for_near_zero_sum(self):
        self.assertFalse(triples_sum_to_zero([1, 2, -2]))

    def test_returns_true_with_negative_zero_and_positive(self):
        self.assertTrue(triples_sum_to_zero([0, -5, 5]))

    def test_returns_false_for_single_zero(self):
        self.assertFalse(triples_sum_to_zero([0]))

    def test_returns_false_for_two_zeros_and_one(self):
        self.assertFalse(triples_sum_to_zero([0, 0, 1]))

    def test_returns_true_for_three_zeros(self):
        self.assertTrue(triples_sum_to_zero([0, 0, 0]))

    def test_returns_true_for_zero_and_opposite_pair(self):
        self.assertTrue(triples_sum_to_zero([0, 7, -7]))

    def test_returns_false_when_only_pair_sums_to_zero(self):
        self.assertFalse(triples_sum_to_zero([1, -1, 2]))

    def test_returns_true_with_multiple_valid_triplets(self):
        self.assertTrue(triples_sum_to_zero([1, -1, 2, -2, 3, -3]))

    def test_passing_none_raises_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero(None)

    def test_passing_string_raises_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero("123")

    def test_passing_integer_raises_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero(123)

    def test_passing_tuple_raises_error(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero((1, 2, 3))

    def test_returns_true_for_float_triplet_summing_to_zero(self):
        self.assertTrue(triples_sum_to_zero([1.5, 2.5, -4.0]))

    def test_returns_false_for_float_triplet_not_summing_to_zero(self):
        self.assertFalse(triples_sum_to_zero([1.5, 2.5, -3.0]))

    def test_returns_true_for_triplet_with_repeated_values(self):
        self.assertTrue(triples_sum_to_zero([2, 2, -4, 10]))

    def test_returns_false_for_list_with_only_one_negative(self):
        self.assertFalse(triples_sum_to_zero([1, 2, 3, -100]))


import unittest

if __name__ == '__main__':
    unittest.main()
